def number_of_patterns(m, n):
    skip = [[0] * 10 for _ in range(10)]
    for a, b, mid in [(1, 3, 2), (4, 6, 5), (7, 9, 8), (1, 7, 4), (2, 8, 5),
                      (3, 9, 6), (1, 9, 5), (3, 7, 5)]:
        skip[a][b] = skip[b][a] = mid
    visited = [False] * 10

    def dfs(cur, length):
        count = 1 if length >= m else 0
        if length == n:
            return count
        visited[cur] = True
        for nxt in range(1, 10):
            mid = skip[cur][nxt]
            if not visited[nxt] and (mid == 0 or visited[mid]):
                count += dfs(nxt, length + 1)
        visited[cur] = False
        return count

    return 4 * dfs(1, 1) + 4 * dfs(2, 1) + dfs(5, 1)   # corner, edge, centre

def number_of_patterns(m, n):
    skip = [[0] * 10 for _ in range(10)]
    for a, b, mid in [(1, 3, 2), (4, 6, 5), (7, 9, 8), (1, 7, 4), (2, 8, 5),
                      (3, 9, 6), (1, 9, 5), (3, 7, 5)]:
        skip[a][b] = skip[b][a] = mid
    visited = [False] * 10

    def dfs(cur, length):
        count = 1 if length >= m else 0
        if length == n:
            return count
        visited[cur] = True
        for nxt in range(1, 10):
            mid = skip[cur][nxt]
            if not visited[nxt] and (mid == 0 or visited[mid]):
                count += dfs(nxt, length + 1)
        visited[cur] = False
        return count

    return sum(dfs(k, 1) for k in range(1, 10))
